function dateField(key,label,help='',opts={}){return {key,label,help,type:'date',...opts}}
function optionMarkup(f,value){let choices=typeof f.choices==='function'?f.choices():f.choices||[];return choices.map(item=>{let val=Array.isArray(item)?item[0]:item[f.valueKey||'id'];let name=Array.isArray(item)?item[1]:item[f.labelKey||'name'];let suffix=f.suffixKey&&item[f.suffixKey]?` · ${item[f.suffixKey]}`:'';return `<option value="${esc(val)}" ${String(val)===String(value??'')?'selected':''}>${esc(name)}${esc(suffix)}</option>`}).join('')}
function nestedValue(obj,path){return path.split('.').reduce((acc,key)=>acc?.[key],obj)}
function fieldHtml(f){const key=f.key,raw=nestedValue(state[current],key),value=raw??'';const span=f.span==='full'?' full':'';const help=f.help?`<div class="help">${esc(f.help)}</div>`:'';if(f.type==='checkbox')return `<div class="field${span}"><div class="check-card"><input type="checkbox" data-setting-key="${esc(key)}" ${raw?'checked':''}><div><label>${esc(f.label)}</label>${help}</div></div></div>`;if(f.type==='file'){const logo=state.business?.logo_url?`<img src="${esc(state.business.logo_url)}" alt="Business logo">`:'Logo';return `<div class="field${span}"><label>${esc(f.label)}</label><div class="logo-row"><div class="logo-preview" id="logoPreview">${logo}</div><input type="file" class="control" id="businessLogo" accept="image/png,image/jpeg,image/webp"> </div>${help}</div>`}if(f.type==='select'){let optionsHtml=optionMarkup(f,value);if(f.allowCustom&&!f.choices().some(i=>String(Array.isArray(i)?i[0]:i[f.valueKey||'id'])===String(value))){optionsHtml+=`<option value="${esc(value)}" selected>${esc(value)}</option>`}return `<div class="field${span}"><label>${esc(f.label)}</label><select class="select" data-setting-key="${esc(key)}" ${f.nullable?'data-nullable="1"':''}>${optionsHtml}</select>${help}</div>`}if(f.multiline)return `<div class="field${span}"><label>${esc(f.label)}</label><textarea class="textarea" data-setting-key="${esc(key)}" placeholder="${esc(f.placeholder||'')}">${esc(value)}</textarea>${help}</div>`;const inputType=f.type==='date'?'date':f.type==='number'?'number':'text';return `<div class="field${span}"><label>${esc(f.label)}</label><input class="control" type="${inputType}" data-setting-key="${esc(key)}" ${key==='currency'?'list="currencyOptions"':''} value="${esc(value)}" ${f.required?'required':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.maxLength?`maxlength="${f.maxLength}"`:''} ${f.step?`step="${f.step}"`:''} ${f.placeholder?`placeholder="${esc(f.placeholder)}"`:''} ${f.nullable?'data-nullable="1"':''}>${f.suffix?`<div class="help">${esc(f.suffix)}</div>`:''}${help}</div>`}
function renderSide(){document.getElementById('side').innerHTML='<div class="side-label">Settings sections</div>'+categories.map(([id,icon,label])=>`<button type="button" data-category="${id}" class="${current===id?'active':''}"><span class="side-icon">${icon}</span>${label}</button>`).join('')}
function renderPanel(){const category=categories.find(item=>item[0]===current);const sections=schemas[current]||[];const body=sections.map(section=>`<section class="group"><h3 class="group-title">${esc(section.title)}</h3>${section.note?`<div class="subsection-note">${esc(section.note)}</div>`:''}<div class="${current==='modules'||(current==='dashboard'&&section.title==='Dashboard widgets')?'toggle-grid':current==='prefixes'?'prefix-grid':'grid'}">${(section.fields||[]).map(fieldHtml).join('')}</div></section>`).join('');document.getElementById('settingsPanel').innerHTML=`<div class="content-head"><div><h2>${esc(category[2])} Settings</h2><p>Changes are saved for <strong>${esc(state.business?.name||'this business')}</strong> and shared across authorized clients.</p></div>${current==='tax'?'<a class="external-link" href="/taxes">Open Tax Rates &amp; Groups →</a>':''}</div><div class="content-body" id="settingsForm">${body||'<div class="empty">No controls in this section yet.</div>'}</div><datalist id="currencyOptions">${(options.currencies||[]).map(currency=>`<option value="${esc(currency.code)}">${esc(currency.name)}</option>`).join('')}</datalist><div class="actions"><small>Only users with <code>settings.manage</code> can save these changes.</small><button class="btn primary" data-save-settings>Save ${esc(category[2])} Settings</button></div>`;renderSide()}
async function api(path,opts={}){const method=opts.method||'GET',headers={'Accept':'application/json',...(opts.headers||{})};if(opts.body&&!(opts.body instanceof FormData)){headers['Content-Type']='application/json';headers['X-CSRF-TOKEN']=csrf}else if(opts.body instanceof FormData){headers['X-CSRF-TOKEN']=csrf}const response=await fetch(path.startsWith('http')?path:settingsUrl+path,{method,credentials:'same-origin',headers,body:opts.body?(opts.body instanceof FormData?opts.body:JSON.stringify(opts.body)):undefined});const result=await response.json().catch(()=>({}));if(response.status===401){window.location.href=document.body.dataset.loginUrl;throw new Error('Sign in again to continue.')}if(!response.ok){const first=result.errors?Object.values(result.errors).flat()[0]:null;throw new Error(first||result.message||'The request could not be completed.')}return result}
function showAlert(message,type='success'){const el=document.getElementById('alert');el.textContent=message;el.className='alert show '+(type==='error'?'error':'success');clearTimeout(showAlert.timer);showAlert.timer=setTimeout(()=>el.classList.remove('show'),5000)}
function setPath(object,path,value){const parts=path.split('.');let target=object;while(parts.length>1){const part=parts.shift();target[part]??={};target=target[part]}target[parts[0]]=value}
async function loadSettings(){try{const response=await api('');state=response.data||{};options=response.options||{};renderPanel()}catch(error){document.getElementById('settingsPanel').innerHTML=`<div class="empty">Settings could not be loaded.</div>`;showAlert(error.message,'error')}}
async function saveSettings(){const body={};document.querySelectorAll('#settingsForm [data-setting-key]').forEach(element=>{const key=element.dataset.settingKey;let value;if(element.type==='checkbox')value=element.checked;else if(element.type==='number')value=element.value===''?(element.dataset.nullable?null:0):Number(element.value);else if(element.dataset.nullable&&element.value==='')value=null;else value=element.value;setPath(body,key,value)});try{const response=await api('',{method:'PATCH',body:{category:current,settings:body}});state=response.data||state;showAlert(`${categories.find(item=>item[0]===current)[2]} settings saved.`);renderPanel()}catch(error){showAlert(error.message,'error')}}
document.addEventListener('click',event=>{const category=event.target.closest('[data-category]');if(category){current=category.dataset.category;renderPanel();return}if(event.target.closest('[data-save-settings]'))saveSettings()});
document.addEventListener('change',async event=>{if(event.target.id!=='businessLogo'||!event.target.files?.[0])return;const form=new FormData();form.append('logo',event.target.files[0]);try{const response=await api('/logo',{method:'POST',body:form});state=response.data||state;showAlert('Business logo uploaded.');renderPanel()}catch(error){showAlert(error.message,'error')}});
loadSettings();
</script>
</body>
</html>
